import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import { duration, t } from '../util';
const TYPES = ['audio/webm;codecs=opus', 'audio/webm', 'audio/mp4', 'audio/ogg;codecs=opus'];

/**
 * A voice note, recorded in the browser with MediaRecorder: Opus in WebM
 * where the browser has it, AAC in MP4 on Safari. Stops by itself at the
 * forum's length limit; nothing leaves the browser until you attach it.
 */
export default class VoiceRecorder extends Component {
  recorder = null;
  stream = null;
  chunks = [];
  started = 0;
  elapsed = 0;
  timer = 0;
  blob = null;
  preview = null;
  error = null;
  oncreate(vnode) {
    super.oncreate(vnode);
    this.start();
  }
  onremove(vnode) {
    super.onremove(vnode);
    this.cleanup();
    if (this.preview) URL.revokeObjectURL(this.preview);
  }
  start() {
    this.blob = null;
    if (this.preview) URL.revokeObjectURL(this.preview);
    this.preview = null;
    this.chunks = [];
    navigator.mediaDevices?.getUserMedia({
      audio: true
    }).then(stream => {
      this.stream = stream;
      const type = TYPES.find(x => window.MediaRecorder.isTypeSupported?.(x)) || '';
      this.recorder = new MediaRecorder(stream, type ? {
        mimeType: type,
        audioBitsPerSecond: 48000
      } : undefined);
      this.recorder.ondataavailable = e => e.data.size && this.chunks.push(e.data);
      this.recorder.onstop = () => this.stopped();
      this.recorder.start(250);
      this.started = Date.now();
      this.timer = window.setInterval(() => {
        this.elapsed = Date.now() - this.started;
        if (this.elapsed >= this.attrs.max * 1000) this.stop();
        m.redraw();
      }, 200);
      m.redraw();
    }).catch(() => {
      this.error = String(t('voice.denied'));
      m.redraw();
    });
  }
  stop() {
    if (this.recorder && this.recorder.state !== 'inactive') this.recorder.stop();
  }
  stopped() {
    this.elapsed = Math.min(Date.now() - this.started, this.attrs.max * 1000);
    const type = this.recorder?.mimeType || 'audio/webm';
    this.blob = new Blob(this.chunks, {
      type
    });
    this.preview = URL.createObjectURL(this.blob);
    this.cleanup();
    m.redraw();
  }
  cleanup() {
    clearInterval(this.timer);
    this.stream?.getTracks().forEach(track => track.stop());
    this.stream = null;
  }
  view() {
    if (this.error) {
      return m("div", {
        className: "MomentVoiceRecorder MomentVoiceRecorder--error",
        role: "alert"
      }, m("span", null, this.error), m(Button, {
        className: "Button Button--flat",
        onclick: () => this.attrs.oncancel()
      }, t('voice.close')));
    }
    if (this.blob && this.preview) {
      return m("div", {
        className: "MomentVoiceRecorder"
      }, m("audio", {
        controls: true,
        src: this.preview
      }), m("span", {
        className: "MomentVoiceRecorder-time"
      }, duration(this.elapsed)), m(Button, {
        className: "Button Button--flat",
        icon: "fas fa-rotate-left",
        onclick: () => this.start()
      }, t('voice.again')), m(Button, {
        className: "Button Button--flat",
        onclick: () => this.attrs.oncancel()
      }, t('voice.discard')), m(Button, {
        className: "Button Button--primary",
        icon: "fas fa-check",
        onclick: () => this.attrs.ondone(this.blob, this.elapsed, this.blob.type)
      }, t('voice.attach')));
    }
    return m("div", {
      className: "MomentVoiceRecorder is-recording"
    }, m("span", {
      className: "MomentVoiceRecorder-dot",
      "aria-hidden": "true"
    }), m("span", {
      className: "MomentVoiceRecorder-time",
      "aria-live": "off"
    }, duration(this.elapsed) || '0:00', " / ", duration(this.attrs.max * 1000)), m("span", {
      className: "MomentVoiceRecorder-label"
    }, t('voice.recording')), m(Button, {
      className: "Button Button--flat",
      onclick: () => this.attrs.oncancel()
    }, t('voice.discard')), m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-stop",
      disabled: !this.recorder,
      onclick: () => this.stop()
    }, t('voice.stop')));
  }
}
flarum.reg.add('ernestdefoe-moments', 'forum/components/VoiceRecorder', VoiceRecorder);